// This allocation and function definition execute only when you run cell 1.
data := []float64{12, 15, 18, 21}
original := &data[0]
setupRuns := 1
calls := 0
mean := func(values []float64) (float64, error) {
    if len(values) == 0 { return 0, fmt.Errorf("mean requires a nonempty sample") }
    calls++
    total := 0.0
    for _, value := range values { total += value }
    return total / float64(len(values)), nil
}
fmt.Println("setup once")

// Repeat this cell: mean, data and its captured counter remain in RAM.
value, err := mean(data)
if err != nil { panic(err) }
fmt.Printf("mean=%.1f calls=%d setup=%d same=%t\n", value, calls, setupRuns, original == &data[0])
